// hashStubInstance is the instance of a partitiontest.HashStub that the
// checks of the constructors and the options drive.
type hashStubInstance = stub.Instance[partitiontest.HashSum64Call]

// hashStubInstanceOf returns the instance of s. The options apply to the
// whole double, so the checks call Sum64 alone.
func hashStubInstanceOf(tb assert.TB, s *partitiontest.HashStub) hashStubInstance {
	tb.Helper()
	return hashStubInstance{
		Stub: s.OnSum64.MethodStub,
		Call: func() {
			_ = hashStubSum64(tb, s)
		},
		Reset: s.ResetCalls,
	}
}

// TestHashStub checks the methods, the constructors and the options of the
// double HashStub.
func TestHashStub(t *testing.T) {
	t.Parallel()

	t.Run("Sum64", func(t *testing.T) {
		t.Parallel()
		stub.Behaviour(t, "Sum64", hashStubSum64Subject)

		t.Run("records the arguments of the call", func(t *testing.T) {
			t.Parallel()
			s := partitiontest.NewHashStub(t)
			_ = hashStubSum64(t, s)
			got := s.OnSum64.AssertCalledOnce(t, "Sum64 records the call")
			a0 := hashStubSum64Args(t)
			assert.Equal(t, got.Key, a0, "the call records Key")
		})

		t.Run("runs the OnRecord hook once for each call", func(t *testing.T) {
			t.Parallel()
			s := partitiontest.NewHashStub(t)
			var seen []partitiontest.HashSum64Call
			s.OnSum64.OnRecord(func(c partitiontest.HashSum64Call) { seen = append(seen, c) })
			_ = hashStubSum64(t, s)
			_ = hashStubSum64(t, s)
			assert.Length(t, seen, 2, "OnRecord runs once for each call of Sum64")
		})
	})

	t.Run("Version", func(t *testing.T) {
		t.Parallel()
		stub.Behaviour(t, "Version", hashStubVersionSubject)

		t.Run("runs the OnRecord hook once for each call", func(t *testing.T) {
			t.Parallel()
			s := partitiontest.NewHashStub(t)
			var seen []partitiontest.HashVersionCall
			s.OnVersion.OnRecord(func(c partitiontest.HashVersionCall) { seen = append(seen, c) })
			_ = hashStubVersion(t, s)
			_ = hashStubVersion(t, s)
			assert.Length(t, seen, 2, "OnRecord runs once for each call of Version")
		})
	})

	t.Run("ResetCalls", func(t *testing.T) {
		t.Parallel()
		stub.ResetBehaviour(t, func(tb assert.TB) hashStubInstance {
			return hashStubInstanceOf(tb, partitiontest.NewHashStub(tb))
		})

		t.Run("clears the recorded calls of Sum64", func(t *testing.T) {
			t.Parallel()
			s := partitiontest.NewHashStub(t)
			_ = hashStubSum64(t, s)
			s.ResetCalls()
			assert.Equal(t, s.OnSum64.CallCount(), 0, "ResetCalls clears the calls of Sum64")
		})

		t.Run("keeps the results of Returns of Sum64", func(t *testing.T) {
			t.Parallel()
			s := partitiontest.NewHashStub(t)
			want0 := hashStubSum64Pins()
			s.OnSum64.Returns(want0)
			s.ResetCalls()
			got0 := hashStubSum64(t, s)
			assert.Equal(t, got0, want0, "ResetCalls keeps the Result of Sum64")
		})

		t.Run("clears the recorded calls of Version", func(t *testing.T) {
			t.Parallel()
			s := partitiontest.NewHashStub(t)
			_ = hashStubVersion(t, s)
			s.ResetCalls()
			assert.Equal(t, s.OnVersion.CallCount(), 0, "ResetCalls clears the calls of Version")
		})

		t.Run("keeps the results of Returns of Version", func(t *testing.T) {
			t.Parallel()
			s := partitiontest.NewHashStub(t)
			want0 := hashStubVersionPins()
			s.OnVersion.Returns(want0)
			s.ResetCalls()
			got0 := hashStubVersion(t, s)
			assert.Equal(t, got0, want0, "ResetCalls keeps the Result of Version")
		})
	})

	t.Run("NewHashStubDelayed", func(t *testing.T) {
		t.Parallel()
		stub.LatencyBehaviour(t, func(tb assert.TB, d time.Duration, clk assert.Clock) hashStubInstance {
			return hashStubInstanceOf(tb, partitiontest.NewHashStubDelayed(tb, d, clk))
		})
	})

	t.Run("HashStubStrict", func(t *testing.T) {
		t.Parallel()
		stub.StrictBehaviour(t, func(tb assert.TB) hashStubInstance {
			return hashStubInstanceOf(tb, partitiontest.NewHashStub(tb, partitiontest.HashStubStrict()))
		})
	})

	t.Run("HashStubDelegateTo", func(t *testing.T) {
		t.Parallel()

		t.Run("passes Sum64 to the implementation", func(t *testing.T) {
			t.Parallel()
			inner := partitiontest.NewHashStub(t)
			s := partitiontest.NewHashStub(t, partitiontest.HashStubDelegateTo(inner))
			_ = hashStubSum64(t, s)
			inner.OnSum64.AssertCalledOnce(t, "Sum64 calls the implementation")
		})

		t.Run("passes Version to the implementation", func(t *testing.T) {
			t.Parallel()
			inner := partitiontest.NewHashStub(t)
			s := partitiontest.NewHashStub(t, partitiontest.HashStubDelegateTo(inner))
			_ = hashStubVersion(t, s)
			inner.OnVersion.AssertCalledOnce(t, "Version calls the implementation")
		})
	})

	t.Run("HashStubWithClock", func(t *testing.T) {
		t.Parallel()
		stub.ClockBehaviour(t, func(tb assert.TB, clk assert.Clock) hashStubInstance {
			return hashStubInstanceOf(tb, partitiontest.NewHashStub(tb, partitiontest.HashStubWithClock(clk)))
		})
	})

	t.Run("HashStubWithRandSource", func(t *testing.T) {
		t.Parallel()
		stub.RandSourceBehaviour(t, func(tb assert.TB, src rand.Source) hashStubInstance {
			return hashStubInstanceOf(tb, partitiontest.NewHashStub(tb, partitiontest.HashStubWithRandSource(src)))
		})
	})

	t.Run("HashStubBenchMode", func(t *testing.T) {
		t.Parallel()
		stub.BenchModeBehaviour(t, func(tb assert.TB) hashStubInstance {
			return hashStubInstanceOf(tb, partitiontest.NewHashStub(tb, partitiontest.HashStubBenchMode()))
		})
	})

	t.Run("HashStubWithLatency", func(t *testing.T) {
		t.Parallel()
		stub.LatencyBehaviour(t, func(tb assert.TB, d time.Duration, clk assert.Clock) hashStubInstance {
			return hashStubInstanceOf(
				tb,
				partitiontest.NewHashStub(
					tb,
					partitiontest.HashStubWithClock(clk),
					partitiontest.HashStubWithLatency(d),
				),
			)
		})
	})

	t.Run("WithHashSum64", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the function of Sum64", func(t *testing.T) {
			t.Parallel()
			called := false
			s := partitiontest.NewHashStub(t, partitiontest.WithHashSum64(func(_ []byte) uint64 {
				called = true
				var z0 uint64
				return z0
			}))
			_ = hashStubSum64(t, s)
			assert.True(t, called, "WithHashSum64 sets the function of Sum64")
		})
	})

	t.Run("WithHashVersion", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the function of Version", func(t *testing.T) {
			t.Parallel()
			called := false
			s := partitiontest.NewHashStub(t, partitiontest.WithHashVersion(func() uint32 {
				called = true
				var z0 uint32
				return z0
			}))
			_ = hashStubVersion(t, s)
			assert.True(t, called, "WithHashVersion sets the function of Version")
		})
	})
}

// TestHashSum64Stub checks the methods of HashSum64Stub, which configures
// Sum64.
func TestHashSum64Stub(t *testing.T) {
	t.Parallel()

	t.Run("Returns", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the results of each call of Sum64", func(t *testing.T) {
			t.Parallel()
			s := partitiontest.NewHashStub(t)
			want0 := hashStubSum64Pins()
			s.OnSum64.Returns(want0)
			got0 := hashStubSum64(t, s)
			assert.Equal(t, got0, want0, "Sum64 returns the Result that Returns sets")
		})

		t.Run("configures Sum64 for strict mode", func(t *testing.T) {
			t.Parallel()
			r := assert.NewRecorder()
			s := partitiontest.NewHashStub(r)
			s.OnSum64.Strict()
			var want0 uint64
			s.OnSum64.Returns(want0)
			_ = hashStubSum64(t, s)
			assert.False(t, r.Failed(), "strict mode accepts the call of Sum64")
		})
	})

	t.Run("Func", func(t *testing.T) {
		t.Parallel()

		t.Run("passes the arguments of each call of Sum64 to the function", func(t *testing.T) {
			t.Parallel()
			s := partitiontest.NewHashStub(t)
			var got0 []byte
			s.OnSum64.Func(func(p0 []byte) uint64 {
				got0 = p0
				var z0 uint64
				return z0
			})
			_ = hashStubSum64(t, s)
			a0 := hashStubSum64Args(t)
			assert.Equal(t, got0, a0, "the function receives Key")
		})
	})
}

